(function(){'use strict';var box=document.querySelector('.vs-protected');if(!box)return;var api=box.getAttribute('data-api'),nonce=box.getAttribute('data-nonce'),id=box.getAttribute('data-lesson');var secApi=api.replace(/lesson\/$/,'security/');document.body.classList.add('vs-has-protected');function req(url,method,data){return fetch(url,{method:method||'GET',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-WP-Nonce':nonce},body:data?JSON.stringify(data):undefined}).then(function(r){return r.json().catch(function(){return{};}).then(function(j){if(!r.ok){var e=new Error(j.message||'Something went wrong. Please refresh the page.');e.code=j.code;e.data=j.data||{};throw e;}return j;});});}
function toast(text){var t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';t.setAttribute('role','status');document.body.appendChild(t);}
t.textContent=text;t.classList.add('is-visible');clearTimeout(t._h);t._h=setTimeout(function(){t.classList.remove('is-visible');},3200);}
function watermark(text){var svg='<svg xmlns="http://www.w3.org/2000/svg" width="360" height="200"><text x="20" y="120" transform="rotate(-24 180 100)" font-family="sans-serif" font-size="15" fill="rgba(120,120,120,0.13)">'+
text.replace(/[<>&"]/g,'')+'</text></svg>';var w=document.createElement('div');w.className='vs-mark';w.setAttribute('aria-hidden','true');w.style.backgroundImage='url("data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)+'")';box.appendChild(w);}
function load(){box.classList.remove('is-error');req(api+id).then(function(j){var body=document.createElement('div');body.className='vs-protected-body';body.innerHTML=j.html;box.textContent='';box.appendChild(body);watermark(j.mark||'');box.classList.add('is-loaded');if(window.VSEnhanceCode)window.VSEnhanceCode();if(window.VSViz&&window.VSViz.init)window.VSViz.init();if(window.VSWalk)window.VSWalk();document.dispatchEvent(new CustomEvent('vs:lesson-loaded'));}).catch(problem);}
function card(html){box.classList.add('is-error');box.innerHTML='<div class="vs-protected-card">'+html+'</div>';return box.querySelector('.vs-protected-card');}
function problem(e){if(e.code==='device_switch'){var c=card('<p class="vs-pc-title">📱💻 Premium is open on your other '+(e.data.type==='phone'?'phone':'computer')+'</p>'+'<p>Premium works on one phone and one computer. It is currently on <b class="vs-pc-other"></b>. Use it here instead? The other one will be signed out.</p>'+'<div class="vs-pc-actions"><button type="button" class="btn btn-primary" data-switch>Use this device</button></div><div class="vs-pc-check" hidden></div><p class="vs-pc-msg" aria-live="polite"></p>');c.querySelector('.vs-pc-other').textContent=e.data.other||'another device';c.querySelector('[data-switch]').addEventListener('click',function(){doSwitch(c);});}else if(e.code==='paused'){var p=card('<p class="vs-pc-title">⏸️ Taking a short breather</p><p></p><div class="vs-pc-check"></div><p class="vs-pc-msg" aria-live="polite"></p>');p.querySelector('p:nth-child(2)').textContent=e.message;check(p,'email',load);}else{var x=card('<p class="vs-pc-title">🔒 Can’t open this lesson</p><p></p><button type="button" class="btn btn-ghost btn-sm" data-retry>Try again</button>');x.querySelector('p:nth-child(2)').textContent=e.message;x.querySelector('[data-retry]').addEventListener('click',load);}}
function doSwitch(c){var msg=c.querySelector('.vs-pc-msg');req(api+'switch-device','POST',{}).then(load).catch(function(e){if(e.code==='stepup'){c.querySelector('[data-switch]').hidden=true;check(c,e.data.method,function(){doSwitch(c);});}
else msg.textContent=e.message;});}
function check(c,method,then){var area=c.querySelector('.vs-pc-check'),msg=c.querySelector('.vs-pc-msg');area.hidden=false;area.innerHTML='<p class="vs-pc-sub"></p><div class="pay-code-row"><input type="text" maxlength="9" autocomplete="one-time-code"><button type="button" class="btn btn-primary btn-sm" data-ok>Confirm</button></div>'+
(method==='app'?'':'<button type="button" class="btn-link" data-send>Email me a code</button>');var inp=area.querySelector('input');inp.inputMode=method==='app'?'text':'numeric';inp.placeholder=method==='app'?'Code from your app':'6-digit code';inp.setAttribute('aria-label',inp.placeholder);area.querySelector('.vs-pc-sub').textContent=method==='app'?'Type the code from your authenticator app.':'We’ll email you a 6-digit code.';var send=area.querySelector('[data-send]');if(send)send.addEventListener('click',function(){send.disabled=true;req(secApi+'stepup','POST',{action:'send'}).then(function(j){msg.textContent='📧 Code sent to '+j.to+'.';inp.focus();}).catch(function(e){msg.textContent=e.message;}).then(function(){setTimeout(function(){send.disabled=false;},60000);});});var ok=area.querySelector('[data-ok]');ok.addEventListener('click',function(){ok.disabled=true;req(secApi+'stepup','POST',{action:'check',code:inp.value}).then(then).catch(function(e){msg.textContent=e.message;ok.disabled=false;});});inp.addEventListener('keydown',function(ev){if(ev.key==='Enter')ok.click();});}
function inLesson(node){return node&&box.contains(node.nodeType===1?node:node.parentNode);}
document.addEventListener('copy',function(e){var sel=window.getSelection();if(sel&&sel.rangeCount&&inLesson(sel.anchorNode)){e.preventDefault();toast('Copying premium lesson text is turned off. Code blocks have their own Copy button.');}});document.addEventListener('cut',function(e){if(inLesson(e.target))e.preventDefault();});box.addEventListener('contextmenu',function(e){if(!e.target.closest('input, textarea')){e.preventDefault();toast('Right-click is turned off on premium lessons.');}});box.addEventListener('dragstart',function(e){e.preventDefault();});window.addEventListener('beforeprint',function(){document.body.classList.add('vs-no-print');});window.addEventListener('afterprint',function(){document.body.classList.remove('vs-no-print');});load();})();